<?php
require "config.php"; admin_required(); $title="Verifikasi Surat Izin / Sakit";
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)$_POST['id'];$status=$_POST['status'];$catatan=trim($_POST['catatan']);$uid=$_SESSION['user']['id'];$s=$conn->prepare("UPDATE pengajuan_surat SET status=?,catatan_verifikasi=?,diverifikasi_at=NOW(),diverifikasi_oleh=? WHERE id=?");$s->bind_param("ssii",$status,$catatan,$uid,$id);$s->execute();flash('success','Verifikasi disimpan.');header("Location:verifikasi.php");exit;}
$rows=$conn->query("SELECT p.*,s.nis,s.nama,k.nama_kelas FROM pengajuan_surat p JOIN siswa s ON s.id=p.siswa_id JOIN kelas k ON k.id=s.kelas_id ORDER BY p.status='Menunggu' DESC,p.diajukan_at DESC");include "header.php";?>
<h2>Verifikasi Surat</h2><div class="card table-wrap"><table><tr><th>Siswa</th><th>Jenis</th><th>Periode</th><th>Alasan</th><th>Status</th><th>Aksi</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nis'].' - '.$r['nama'])?></td><td><?=e($r['jenis'])?></td><td><?=e($r['tanggal_mulai'].' s/d '.$r['tanggal_selesai'])?></td><td><?=e($r['alasan'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='Menunggu'):?><form method="post"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option>Disetujui</option><option>Ditolak</option></select><input name="catatan" placeholder="Catatan"><button class="btn">Verifikasi</button></form><?php else:?><?=e($r['catatan_verifikasi'])?><?php endif;?></td></tr><?php endwhile;?></table></div>
<?php include "footer.php"; ?>
